css:
@keyframes fade-in-up {
            from { opacity: 0; transform: translateY(20px); }
            to { opacity: 1; transform: translateY(0); }
        }
        .animate-fade-in-up { animation: fade-in-up 0.5s ease-out forwards; }
        .step-progress { transition: width 0.3s ease-in-out; }
        .resource-card:hover { transform: translateY(-4px); }

        /* Electron orbital animations */
        @keyframes orbit1 { from { transform: rotateX(70deg) rotateZ(0deg); } to { transform: rotateX(70deg) rotateZ(360deg); } }
        @keyframes orbit2 { from { transform: rotateX(60deg) rotateY(30deg) rotateZ(0deg); } to { transform: rotateX(60deg) rotateY(30deg) rotateZ(360deg); } }
        @keyframes orbit3 { from { transform: rotateX(75deg) rotateY(-25deg) rotateZ(0deg); } to { transform: rotateX(75deg) rotateY(-25deg) rotateZ(360deg); } }
        @keyframes orbit4 { from { transform: rotateX(65deg) rotateY(45deg) rotateZ(0deg); } to { transform: rotateX(65deg) rotateY(45deg) rotateZ(360deg); } }
        @keyframes pulse-electron { 0%, 100% { transform: scale(1); opacity: 1; } 50% { transform: scale(1.2); opacity: 0.8; } }

        .electron-orbit-1 { animation: orbit1 3s linear infinite; transform-origin: 150px 120px; }
        .electron-orbit-2 { animation: orbit2 4s linear infinite; transform-origin: 150px 120px; }
        .electron-orbit-3 { animation: orbit3 2.5s linear infinite; transform-origin: 150px 120px; }
        .electron-orbit-4 { animation: orbit4 5s linear infinite; transform-origin: 150px 120px; }
        .electron-pulse { animation: pulse-electron 1.5s ease-in-out infinite; }

        /* Section cards */
        .section-card {
            background: white;
            border-radius: 12px;
            padding: 1.5rem;
            margin-bottom: 1.5rem;
            box-shadow: 0 2px 8px rgba(0,0,0,0.05);
            border: 1px solid #e5e7eb;
        }

        /* Click hint button */
        .click-hint {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 8px;
            background: linear-gradient(135deg, #fef3c7 0%, #fde68a 100%);
            color: #92400e;
            font-size: 1rem;
            font-weight: 600;
            cursor: pointer;
            margin-top: 24px;
            padding: 12px 24px;
            border-radius: 12px;
            border: 2px solid #f59e0b;
            transition: all 0.3s ease;
            animation: pulse-hint 2s infinite;
        }
        .click-hint:hover {
            background: linear-gradient(135deg, #fde68a 0%, #fcd34d 100%);
            transform: translateY(-2px);
            box-shadow: 0 4px 12px rgba(245, 158, 11, 0.4);
        }
        @keyframes pulse-hint {
            0%, 100% { box-shadow: 0 0 0 0 rgba(245, 158, 11, 0.4); }
            50% { box-shadow: 0 0 0 8px rgba(245, 158, 11, 0); }
        }

        /* Step complete indicator */
        .step-complete-hint {
            background: linear-gradient(135deg, #d1fae5 0%, #a7f3d0 100%);
            border: 2px solid #10b981;
            color: #065f46;
            padding: 16px 24px;
            border-radius: 12px;
            text-align: center;
            margin-top: 24px;
        }

        /* Orbital box styles */
        .orbital-box {
            width: 40px;
            height: 30px;
            border: 2px solid #6366f1;
            border-radius: 4px;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            margin: 2px;
            background: #eef2ff;
            position: relative;
            cursor: pointer;
            transition: all 0.2s;
        }
        .orbital-box:hover { background: #c7d2fe; transform: scale(1.05); }
        .orbital-box.filled { background: #818cf8; color: white; }
        .orbital-box .electron-up { color: #dc2626; font-size: 14px; }
        .orbital-box .electron-down { color: #2563eb; font-size: 14px; }

        /* Energy level diagram */
        .energy-level {
            display: flex;
            align-items: center;
            gap: 8px;
            margin: 8px 0;
        }
        .energy-line {
            height: 2px;
            background: #e5e7eb;
            flex-grow: 1;
            position: relative;
        }
        .energy-arrow {
            position: absolute;
            right: -5px;
            top: -4px;
            width: 0;
            height: 0;
            border-left: 5px solid #6b7280;
            border-top: 5px solid transparent;
            border-bottom: 5px solid transparent;
        }
        .electron-dot {
            width: 12px;
            height: 12px;
            border-radius: 50%;
            background: #3b82f6;
            display: inline-block;
            margin: 0 2px;
        }

        /* Prerequisite banner */
        .prerequisite-banner {
            background: linear-gradient(135deg, #fef3c7 0%, #fde68a 100%);
            border: 2px solid #f59e0b;
            border-radius: 12px;
            padding: 16px 20px;
            margin-bottom: 24px;
        }

        /* Interactive atom visualization */
        .atom-container {
            position: relative;
            width: 300px;
            height: 300px;
            margin: 20px auto;
        }
        .nucleus {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            width: 60px;
            height: 60px;
            border-radius: 50%;
            background: radial-gradient(circle, #ef4444 0%, #b91c1c 100%);
            display: flex;
            align-items: center;
            justify-content: center;
            color: white;
            font-weight: bold;
            font-size: 14px;
            z-index: 10;
            box-shadow: 0 4px 12px rgba(239, 68, 68, 0.4);
        }
        .shell {
            position: absolute;
            top: 50%;
            left: 50%;
            border-radius: 50%;
            border: 2px dashed rgba(59, 130, 246, 0.3);
        }
        .shell-1 { width: 100px; height: 100px; margin: -50px 0 0 -50px; }
        .shell-2 { width: 160px; height: 160px; margin: -80px 0 0 -80px; }
        .shell-3 { width: 220px; height: 220px; margin: -110px 0 0 -110px; }
        .shell-4 { width: 280px; height: 280px; margin: -140px 0 0 -140px; }

        @media (max-width: 768px) {
            .atom-container { width: 250px; height: 250px; }
            .shell-1 { width: 80px; height: 80px; margin: -40px 0 0 -40px; }
            .shell-2 { width: 130px; height: 130px; margin: -65px 0 0 -65px; }
            .shell-3 { width: 180px; height: 180px; margin: -90px 0 0 -90px; }
            .shell-4 { width: 230px; height: 230px; margin: -115px 0 0 -115px; }
            .nucleus { width: 50px; height: 50px; font-size: 12px; }
        }
